import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    s = input_data[1]

    up = [False] * (n + 2)
    for i, char in enumerate(s):
        idx = i + 1
        up[idx] = (char == 'U')

    ans = [-1] * (n + 2)

    q = deque()
    for i in range(1, n + 1):
        if not up[i]:
            if i == 1:
                ans[i] = 1
                q.append(i)
        else:
            if i == n:
                ans[i] = 1
                q.append(i)

    while q:
        u = q.popleft()
        if ans[u] == -1:
            continue

        if u == 1:
            prev = n
            new_up = True
        elif u == n:
            prev = 1
            new_up = False
        else:
            if up[u]:
                prev = u - 1
                new_up = False
            else:
                prev = u + 1
                new_up = True

        if prev < 1 or prev > n:
            continue

        if ans[prev] != -1:
            continue

        ans[prev] = ans[u] + 1
        if new_up != up[prev]:
            pass
        else:
            up[prev] = not up[prev]
            q.append(prev)

    print(*(ans[1:n+1]))

if __name__ == "__main__":
    main()
